import re

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.egate.genericepcsim import GenericEPCSIMCommand

__author__ = "Adrianna Pienkowska, Bartosz Odziomek"
__copyright__ = "Copyright (C) 2018, Nokia"
__email__ = "adrianna.pienkowska@nokia.com, bartosz.odziomek@nokia.com"


class WarnRequest(GenericEPCSIMCommand):
    """Warnrequest command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Warnrequest command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(WarnRequest, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.current_ret["INFO"] = []
        self.current_ret["WARN"] = []

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return f"warn_request {self.options}"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_not_configured(line)
                self._parse_error(line)
                self._parse_warning(line)
                self._parse_line_with_ornaments(line)
            except ParsingDone:
                pass
        return super(WarnRequest, self).on_new_line(line, is_full_line)

    _re_configured = re.compile(r"is not configured")

    def _parse_not_configured(self, line):
        if self._regex_helper.search_compiled(WarnRequest._re_configured, line):
            self.set_exception(CommandFailure(self, f"Error: {line}"))
            raise ParsingDone

    _re_error = re.compile(r"(Error:|ERR:)(?P<ERROR>.*)")

    def _parse_error(self, line):
        if self._regex_helper.search_compiled(WarnRequest._re_error, line):
            self.set_exception(CommandFailure(self, f"Error: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone

    _re_warn = re.compile(r"WARN:(?P<WARN>.*)")

    def _parse_warning(self, line):
        if self._regex_helper.search_compiled(WarnRequest._re_warn, line):
            self.current_ret["WARN"].append(self._regex_helper.group("WARN").strip())
            raise ParsingDone

    _re_info_with_ornaments = re.compile(r"\d+:\d+:\d+\.\d+\sINF:.*:\s+(-+|=+)\s+(?P<INFO>.*)\s+(-+|=+)")

    def _parse_line_with_ornaments(self, line):
        if self._regex_helper.search_compiled(WarnRequest._re_info_with_ornaments, line):
            info = self._regex_helper.group("INFO").strip()
            self.current_ret["INFO"].append(info)
            raise ParsingDone


